	for _, opt := range opts {
		opt(&o)
	}
	if o.maxDepth < 0 {
		return o, fmt.Errorf("max depth must be non-negative: %d", o.maxDepth)
	}
	if o.maxDepth == 0 {
		o.maxDepth = defaultMaxDepth
	}
