func (a *astConv) list0(n *Node) []Stmt {
	a.stepWork()
	if n == nil {
		return nil
	}
	out := astSlice(&a.list0Chunk, len(n.Children))
	for i, c := range n.Children {
		a.stepWork()
		out[i] = a.toStmt(astNode(c))
	}
	return out
}

